!function(){const t=document.querySelectorAll(".demo-q-btn"),e=document.getElementById("demoOutput");if(!t.length||!e)return;const n=window.DEMO_CONTEXT||"general";function o(t){return t.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")}function s(t){return o(t.trim()).replace(/\*\*(.+?)\*\*/g,"<strong>$1</strong>").split(/\n\s*\n/).map(t=>{const e=t.split("\n").map(t=>t.trim()).filter(Boolean);return e.length?e.every(t=>/^\d+[.)]\s+/.test(t))?"<ol>"+e.map(t=>"<li>"+t.replace(/^\d+[.)]\s+/,"")+"</li>").join("")+"</ol>":e.every(t=>/^[-*•]\s+/.test(t))?"<ul>"+e.map(t=>"<li>"+t.replace(/^[-*•]\s+/,"")+"</li>").join("")+"</ul>":"<p>"+e.join(" ")+"</p>":""}).join("")}t.forEach(o=>o.addEventListener("click",()=>async function(o){const a=o.dataset.q;t.forEach(t=>t.classList.remove("active")),o.classList.add("active"),t.forEach(t=>t.disabled=!0),e.textContent="Thinking...";try{const t=await fetch(window.getApiUrl("/api/assistant"),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question:a,context:n})});if(!t.ok){const e=await t.json().catch(()=>({}));throw new Error(e.error||"Request failed")}const o=await t.json();e.innerHTML=o.text?s(o.text):"<p>No response received.</p>"}catch(t){e.textContent="Couldn't reach the assistant right now — please try again shortly."}finally{t.forEach(t=>t.disabled=!1)}}(o)))}();
